style.css:
@-moz-document domain("spotify.com") {
/* Definir a imagem de fundo */
    body, .main-root {
        background: url("data:image/jpeg;base64,") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ff69b4 !important; /* Texto rosa bebê */
    }

    /* Texto */
    a, p, span, h1, h2, h3, h4, h5, h6, li {
        color: #ff69b4 !important; /* Rosa bebê */
    }

    /* Botões */
    button {
        background-color: #ffcce5 !important; /* Rosa bebê */
        color: #ff69b4 !important; /* Rosa forte */
        border: 1px solid #ff99cc !important; /* Rosa intermediário */
        border-radius: 5px !important;
    }

    button:hover {
        background-color: #ffb3d9 !important; /* Rosa intermediário */
    }

    /* Capas de álbuns e playlists */
    .main-image-image {
        border: 3px solid #ffcce5 !important; /* Borda rosa bebê */
        border-radius: 12px !important;
        transition: transform 0.3s ease, border-color 0.3s ease;
    }

    .main-image-image:hover {
        transform: scale(1.05);
        border-color: #ff99cc !important; /* Cor mais forte ao hover */
    }
}
